import { createServer } from "node:http";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { randomBytes } from "node:crypto";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_FILE = process.env.BOOKS_FILE || join(__dirname, "books.json");
const PORT = Number(process.env.PORT || 3000);

/** @typedef {{id:string,title:string,author:string,notes:string,status:"reading"|"finished",addedAt:string}} Book */

async function loadBooks() {
  if (!existsSync(DATA_FILE)) return [];
  try {
    const raw = await readFile(DATA_FILE, "utf8");
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

async function saveBooks(/** @type {Book[]} */ books) {
  await mkdir(dirname(DATA_FILE), { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify(data, null, 2) + "\n", "utf8");
}

// Fix: saveBooks should write books, not a stray `data` variable.
async function persist(/** @type {Book[]} */ books) {
  await mkdir(dirname(DATA_FILE), { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2) + "\n", "utf8");
}

function newId() {
  return randomBytes(6).toString("base64url");
}

function escapeHtml(/** @type {string} */ s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function nl2br(/** @type {string} */ s) {
  return escapeHtml(s).replace(/\r?\n/g, "<br>");
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  :root { color-scheme: light dark; }
  * { box-sizing: border-box; }
  body { font: 16px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
         max-width: 720px; margin: 0 auto; padding: 24px 16px 64px; color: #1a1a1a;
         background: #fafafa; }
  h1 { font-size: 1.6rem; margin: 0 0 .4em; }
  h2 { font-size: 1.2rem; margin: 1.6em 0 .5em; border-bottom: 1px solid #ddd; padding-bottom: .25em; }
  a { color: #2563eb; }
  .muted { color: #666; font-size: .9rem; }
  .card { background: #fff; border: 1px solid #e3e3e3; border-radius: 8px;
          padding: 14px 16px; margin-bottom: 12px; }
  .card h3 { margin: 0 0 .2em; font-size: 1.1rem; }
  .row { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
  form.inline { display: inline; }
  input, textarea { font: inherit; padding: 8px 10px; border: 1px solid #ccc; border-radius: 6px; background: #fff; color: inherit; }
  textarea { width: 100%; min-height: 120px; resize: vertical; }
  label { display: block; font-weight: 600; margin: 10px 0 4px; }
  .field { margin-bottom: 12px; }
  .field input { width: 100%; }
  button { font: inherit; padding: 8px 14px; border: 1px solid #2563eb; border-radius: 6px;
           background: #2563eb; color: #fff; cursor: pointer; }
  button.secondary { background: #fff; color: #2563eb; }
  .empty { color: #888; font-style: italic; padding: 8px 0; }
  .tag { display: inline-block; font-size: .75rem; padding: 2px 8px; border-radius: 999px;
         background: #eef2ff; color: #3730a3; }
  .tag.done { background: #dcfce7; color: #166534; }
  nav { margin-bottom: 20px; }
  @media (prefers-color-scheme: dark) {
    body { background: #111; color: #eee; }
    .card { background: #1c1c1c; border-color: #2a2a2a; }
    input, textarea { background: #222; border-color: #444; }
    button.secondary { background: #1c1c1c; }
    h2 { border-color: #333; }
  }
</style>
</head>
<body>
<nav><a href="/">Books</a></nav>
${body}
</body>
</html>`;
}

function homePage(books) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");

  const card = (b) => `<div class="card">
    <div class="row">
      <div>
        <h3><a href="/books/${encodeURIComponent(b.id)}">${escapeHtml(b.title)}</a></h3>
        <div class="muted">by ${escapeHtml(b.author)}</div>
      </div>
      <div>
        ${b.status === "reading"
          ? `<form class="inline" method="post" action="/books/${encodeURIComponent(b.id)}/finish">
               <button class="secondary" type="submit">Mark finished</button>
             </form>`
          : `<span class="tag done">finished</span>`}
      </div>
    </div>
  </div>`;

  const readingHtml = reading.length
    ? reading.map(card).join("")
    : `<div class="empty">Nothing in progress. Add a book to get started.</div>`;
  const finishedHtml = finished.length
    ? finished.map(card).join("")
    : `<div class="empty">No finished books yet.</div>`;

  const form = `<h2>Add a book</h2>
<form method="post" action="/books">
  <div class="field"><label for="title">Title</label>
    <input id="title" name="title" required maxlength="300"></div>
  <div class="field"><label for="author">Author</label>
    <input id="author" name="author" required maxlength="200"></div>
  <div class="field"><label for="notes">Notes</label>
    <textarea id="notes" name="notes" placeholder="Optional"></textarea></div>
  <button type="submit">Add book</button>
</form>`;

  return layout("My Books", `
    <h1>My Books</h1>
    <h2>Currently reading</h2>
    ${readingHtml}
    <h2>Finished</h2>
    ${finishedHtml}
    ${form}
  `);
}

function bookPage(b, req) {
  const base = `${req.headers["x-forwarded-proto"] || "http"}://${req.headers.host}`;
  const url = `${base}/books/${encodeURIComponent(b.id)}`;
  return layout(b.title, `
    <h1>${escapeHtml(b.title)}</h1>
    <div class="muted">by ${escapeHtml(b.author)}</div>
    <p><span class="tag ${b.status === "finished" ? "done" : ""}">${b.status}</span></p>

    <h2>Notes</h2>
    <div class="card">${b.notes ? nl2br(b.notes) : `<span class="empty">No notes yet.</span>`}</div>

    <form method="post" action="/books/${encodeURIComponent(b.id)}/notes">
      <div class="field"><label for="notes">Edit notes</label>
        <textarea id="notes" name="notes">${escapeHtml(b.notes)}</textarea></div>
      <button type="submit">Save notes</button>
    </form>

    <p style="margin-top:24px">
      <a href="/">Back to all books</a>
    </p>
    <p class="muted">Share link: <a href="${escapeHtml(url)}">${escapeHtml(url)}</a></p>
  `);
}

/** Parse application/x-www-form-urlencoded body. */
function parseBody(req) {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (c) => {
      data += c;
      if (data.length > 1e5) reject(new Error("body too large"));
    });
    req.on("end", () => {
      const params = {};
      for (const part of data.split("&")) {
        if (!part) continue;
        const [k, v = ""] = part.split("=");
        params[decodeURIComponent(k.replace(/\+/g, " "))] = decodeURIComponent(
          v.replace(/\+/g, " ")
        );
      }
      resolve(params);
    });
    req.on("error", reject);
  });
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, "http://localhost");
    const path = url.pathname;

    if (req.method === "GET" && path === "/") {
      const books = await loadBooks();
      res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
